sys_ui_action.script:
// bfd_ui_mark_duplicate — run the duplicate detector and, when a prior case is
// found, link this case to the original and bump the recurrence count.
(function markDuplicateAction() {
    var CASE_TABLE = 'x_1755386_safetr_0_bfd_fraud_dispute_case';
    var detector = new bfd_DuplicateDetector();
    var engine = new bfd_TriageEngine();

    var found = detector.findDuplicate(current);

    if (!found || found.isDuplicate !== true || !found.originalCaseSysId) {
        gs.addInfoMessage(
            'No duplicate or recurring dispute was found for this customer. The case has been left unchanged.'
        );
        engine.logAiDecision(current, {
            note: 'Agent ran duplicate detection — no matching prior case found.',
            finalDecision: 'duplicate_check_no_match',
        });
        current.update();
        action.setRedirectURL(current);
        return;
    }

    // linkDuplicate sets duplicate_of_case + recurrence_count on the record.
    var customerMessage = detector.linkDuplicate(current);

    var originalNumber = found.originalCaseSysId;
    var original = new GlideRecord(CASE_TABLE);
    if (original.get(found.originalCaseSysId)) {
        originalNumber = original.getValue('case_number') || found.originalCaseSysId;
    }

    engine.logAiDecision(current, {
        note:
            'Agent marked this case as a duplicate of ' +
            originalNumber +
            '. Reason: ' +
            (found.reason || 'matching customer / transaction pattern') +
            '. Prior matching cases: ' +
            (found.priorCount || 0) +
            '.',
        finalDecision: 'marked_duplicate_of=' + originalNumber,
    });
    current.update();

    gs.addInfoMessage(
        'Duplicate found: this case has been linked to original case ' +
            originalNumber +
            ' and the recurrence count has been incremented. Reason: ' +
            (found.reason || 'matching customer / transaction pattern')
    );
    if (customerMessage) {
        gs.addInfoMessage('Customer-facing wording: ' + customerMessage);
    }
    action.setRedirectURL(current);
})();
